          "python tools/lcwext.py lint logicapp/integration.workflow.json --timeout PT1H",
          "# 4  GCC High through two transient failures",
          "python tools/lcwext.py run logicapp/integration.workflow.json \\",
          "    tests/fixtures/trigger-leaver.json --cloud GCCHigh --fail 503,503",
